(() => {
  'use strict';
  const KEY = 'ruka_costos_recetas_v1';
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const uid = (p='id') => `${p}_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
  const todayISO = () => new Date().toISOString().slice(0,10);
  const nowISO = () => new Date().toISOString();
  const fmtDate = (iso) => iso ? new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${iso}T12:00:00`)) : '—';
  const fmtDateTime = (iso) => iso ? new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(iso)) : '—';
  const num = (v) => Number(String(v ?? '').replace(',','.')) || 0;
  const esc = (s='') => String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));

  const defaultState = () => ({
    version: 1,
    settings: { onboarded:false, name:'', business:'', currency:'$', hourValue:5000, defaultMargin:50, defaultWaste:5, pricingMode:'margin' },
    ingredients: [], recipes: [], customers: [], orders: [], production: [], sales: [], expenses: [], notes: [], priceHistory: [], demoLoaded:false
  });

  let state = loadState();
  let currentScreen = 'home';
  let recipeFilter = 'Todas';

  function loadState(){
    try { const raw = localStorage.getItem(KEY); return raw ? {...defaultState(), ...JSON.parse(raw)} : defaultState(); }
    catch { return defaultState(); }
  }
  function saveState(){ localStorage.setItem(KEY, JSON.stringify(state)); }
  function currency(v){ return `${state.settings.currency === '$' ? '$' : state.settings.currency+' '}${Math.round(num(v)).toLocaleString('es-AR')}`; }
  function clamp(n,min,max){ return Math.min(max,Math.max(min,n)); }

  const unitFamily = (u) => ({kg:'mass',g:'mass',l:'vol',ml:'vol',unidad:'unit',docena:'unit'}[u] || u);
  const toBase = (q,u) => {
    q=num(q); if(u==='kg') return q*1000; if(u==='l') return q*1000; if(u==='docena') return q*12; return q;
  };
  function ingredientUseCost(ingredient, qty, unit){
    if(!ingredient) return 0;
    if(unitFamily(ingredient.purchaseUnit)!==unitFamily(unit)) return 0;
    const baseBuy = toBase(ingredient.purchaseQty, ingredient.purchaseUnit);
    const baseUse = toBase(qty, unit);
    return baseBuy > 0 ? num(ingredient.price) * baseUse / baseBuy : 0;
  }
  function calcRecipe(recipe){
    const ingredientCost = (recipe.ingredients||[]).reduce((s,it)=>s+ingredientUseCost(state.ingredients.find(x=>x.id===it.ingredientId), it.qty, it.unit),0);
    const packaging=num(recipe.packaging), labor = num(recipe.laborHours) * num(state.settings.hourValue), utilities=num(recipe.utilities), decoration=num(recipe.decoration), commission=num(recipe.commission), other=num(recipe.other);
    const subtotal = ingredientCost + packaging + labor + utilities + decoration + commission + other;
    const wastePct = num(recipe.wastePct ?? state.settings.defaultWaste);
    const waste = subtotal * clamp(wastePct,0,100)/100;
    const total = subtotal + waste;
    const yieldQty = Math.max(1,num(recipe.yieldQty)||1);
    const unitCost = total / yieldQty;
    const margin = clamp(num(recipe.margin ?? state.settings.defaultMargin),0,95);
    const markup = clamp(num(recipe.markup ?? margin),0,1000);
    const sellUnit = (recipe.pricingMode||state.settings.pricingMode)==='markup' ? unitCost*(1+markup/100) : unitCost/(1-margin/100);
    return {ingredientCost,packaging,labor,utilities,decoration,commission,other,waste,total,unitCost,sellUnit,profitUnit:sellUnit-unitCost,profitTotal:(sellUnit-unitCost)*yieldQty};
  }
  function orderTotals(o){ const total=num(o.qty)*num(o.unitPrice); const paid=num(o.paid); return {total,paid,balance:Math.max(0,total-paid)}; }
  function dateInRange(date, days){ const d=new Date(`${date}T12:00:00`), t=new Date(); t.setHours(12,0,0,0); const start=new Date(t); start.setDate(t.getDate()-days+1); return d>=start && d<=t; }

  function demoData(){
    const flour={id:uid('ing'),name:'Harina 0000',category:'Secos',brand:'',purchaseQty:1,purchaseUnit:'kg',price:1800,date:todayISO(),provider:'',notes:'',createdAt:nowISO(),updatedAt:nowISO(),demo:true};
    const choc={id:uid('ing'),name:'Chocolate cobertura',category:'Chocolate',brand:'',purchaseQty:1,purchaseUnit:'kg',price:8000,date:todayISO(),provider:'',notes:'',createdAt:nowISO(),updatedAt:nowISO(),demo:true};
    const butter={id:uid('ing'),name:'Manteca',category:'Lácteos',brand:'',purchaseQty:200,purchaseUnit:'g',price:3200,date:todayISO(),provider:'',notes:'',createdAt:nowISO(),updatedAt:nowISO(),demo:true};
    const eggs={id:uid('ing'),name:'Huevos',category:'Frescos',brand:'',purchaseQty:12,purchaseUnit:'unidad',price:4800,date:todayISO(),provider:'',notes:'',createdAt:nowISO(),updatedAt:nowISO(),demo:true};
    state.ingredients.push(flour,choc,butter,eggs);
    const cookie={id:uid('rec'),name:'Cookies Triple Chocolate',category:'Cookies',description:'Cookies intensas, suaves por dentro y crocantes por fuera.',ingredients:[{ingredientId:flour.id,qty:350,unit:'g'},{ingredientId:choc.id,qty:250,unit:'g'},{ingredientId:butter.id,qty:180,unit:'g'},{ingredientId:eggs.id,qty:2,unit:'unidad'}],procedure:'Mezclar manteca y azúcar. Incorporar huevos, secos y chocolate. Porcionar, enfriar y hornear.',prepTime:20,cookTime:14,temp:175,yieldQty:12,yieldUnit:'unidades',packaging:850,laborHours:.5,utilities:350,decoration:0,commission:0,other:0,wastePct:5,margin:50,pricingMode:'margin',favorite:true,notes:'',createdAt:nowISO(),updatedAt:nowISO(),demo:true};
    const brownie={id:uid('rec'),name:'Brownies clásicos',category:'Brownies',description:'Brownie húmedo de chocolate.',ingredients:[{ingredientId:flour.id,qty:160,unit:'g'},{ingredientId:choc.id,qty:300,unit:'g'},{ingredientId:butter.id,qty:180,unit:'g'},{ingredientId:eggs.id,qty:4,unit:'unidad'}],procedure:'Fundir chocolate y manteca. Agregar huevos y luego harina. Hornear hasta que el centro quede húmedo.',prepTime:15,cookTime:25,temp:170,yieldQty:16,yieldUnit:'porciones',packaging:700,laborHours:.4,utilities:300,decoration:0,commission:0,other:0,wastePct:5,margin:50,pricingMode:'margin',favorite:false,notes:'',createdAt:nowISO(),updatedAt:nowISO(),demo:true};
    state.recipes.push(cookie,brownie);
    const customer={id:uid('cus'),name:'María López',phone:'11 5555-0000',instagram:'',address:'',notes:'Prefiere entregas por la tarde.',createdAt:nowISO(),updatedAt:nowISO(),demo:true}; state.customers.push(customer);
    const cc=calcRecipe(cookie); const order={id:uid('ord'),customerId:customer.id,recipeId:cookie.id,product:'Cookies Triple Chocolate',qty:24,unitPrice:Math.ceil(cc.sellUnit/100)*100,paid:15000,orderDate:todayISO(),deliveryDate:todayISO(),deliveryTime:'17:00',deliveryMode:'Retiro',address:'',notes:'Caja regalo',status:'EN PREPARACIÓN',createdAt:nowISO(),updatedAt:nowISO(),demo:true}; state.orders.push(order);
    state.production.push({id:uid('prod'),orderId:order.id,recipeId:cookie.id,product:order.product,qty:order.qty,date:todayISO(),status:'En proceso',notes:'',createdAt:nowISO(),updatedAt:nowISO(),demo:true});
    state.expenses.push({id:uid('exp'),date:todayISO(),category:'Ingredientes',description:'Compra de chocolate y manteca',amount:21500,notes:'',createdAt:nowISO(),updatedAt:nowISO(),demo:true});
    state.notes.push({id:uid('note'),date:todayISO(),text:'Revisar stock de cajas antes del viernes.',createdAt:nowISO(),demo:true});
    state.demoLoaded=true;
  }

  function toast(msg){ const t=$('#toast'); t.textContent=msg; t.classList.remove('hidden'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>t.classList.add('hidden'),2400); }
  function openModal(title, html, onOpen){ $('#modalTitle').textContent=title; $('#modalBody').innerHTML=html; $('#modalBackdrop').classList.remove('hidden'); $('#modal').classList.remove('hidden'); setTimeout(()=>onOpen?.($('#modalBody')),0); }
  function closeModal(){ $('#modalBackdrop').classList.add('hidden'); $('#modal').classList.add('hidden'); $('#modalBody').innerHTML=''; }
  function openMore(){ $('#sheetBackdrop').classList.remove('hidden'); $('#moreSheet').classList.remove('hidden'); }
  function closeMore(){ $('#sheetBackdrop').classList.add('hidden'); $('#moreSheet').classList.add('hidden'); }
  function setActiveNav(screen){ $$('.nav-item').forEach(b=>b.classList.toggle('active', b.dataset.nav===screen || (screen==='more'&&b.dataset.nav==='more'))); }

  function render(screen=currentScreen){ currentScreen=screen; const main=$('#mainContent'); main.innerHTML=''; if(['home','recipes','costs','orders'].includes(screen)) setActiveNav(screen); else setActiveNav('more');
    const fn={home:renderHome,recipes:renderRecipes,costs:renderCosts,orders:renderOrders,production:renderProduction,customers:renderCustomers,finances:renderFinances,ingredients:renderIngredients,shopping:renderShopping,history:renderHistory,settings:renderSettings}[screen]||renderHome; fn(main); main.focus({preventScroll:true}); window.scrollTo({top:0,behavior:'smooth'}); }

  function financeSummary(){
    const month=todayISO().slice(0,7);
    const sales=state.sales.filter(s=>s.date?.startsWith(month));
    const orders=state.orders.filter(o=>o.orderDate?.startsWith(month));
    const revenue = sales.reduce((s,x)=>s+num(x.amount),0) + orders.filter(o=>o.status!=='ENTREGADO').reduce((s,o)=>s+orderTotals(o).paid,0);
    const billed = orders.reduce((s,o)=>s+orderTotals(o).total,0) + sales.filter(s=>!s.orderId).reduce((s,x)=>s+num(x.amount),0);
    const collected = orders.reduce((s,o)=>s+orderTotals(o).paid,0) + sales.filter(s=>!s.orderId).reduce((s,x)=>s+num(x.amount),0);
    const pending = orders.reduce((s,o)=>s+orderTotals(o).balance,0);
    const expenses = state.expenses.filter(e=>e.date?.startsWith(month)).reduce((s,e)=>s+num(e.amount),0);
    const productionCost = orders.reduce((s,o)=>{ const r=state.recipes.find(x=>x.id===o.recipeId); return s+(r?calcRecipe(r).unitCost*num(o.qty):0); },0);
    const profit = billed - productionCost - expenses;
    return {revenue,billed,collected,pending,expenses,productionCost,profit};
  }

  function renderHome(main){
    const f=financeSummary(); const today=todayISO(); const upcoming=state.orders.filter(o=>o.deliveryDate>=today && o.status!=='ENTREGADO' && o.status!=='CANCELADO').sort((a,b)=>(a.deliveryDate+a.deliveryTime).localeCompare(b.deliveryDate+b.deliveryTime)).slice(0,4);
    const prod=state.production.filter(p=>p.date===today).slice(0,5);
    main.innerHTML=`
      <section class="hero"><div><div class="eyebrow">${esc(state.settings.business||'Tu emprendimiento')}</div><h1>Hola, ${esc(state.settings.name||'Pastelera')} 👋</h1><div class="date-line">${fmtDate(today)}</div><p>Así viene tu emprendimiento hoy.</p></div><img src="./ruka-cocina.png" alt="Utensilios y calculadora de pastelería"></section>
      <section class="section"><div class="section-title"><div><h2>Resumen</h2><p>Los números más importantes del mes.</p></div></div><div class="metric-grid">
        ${metric('Facturación',currency(f.billed),'Mes actual','blue')}${metric('Cobrado',currency(f.collected),'Ingresado','olive')}${metric('Pendiente',currency(f.pending),'Por cobrar','pink')}${metric('Ganancia est.',currency(f.profit),'Estimación','beige')}
      </div></section>
      <section class="section visual-card"><img src="./ruka-app-showcase.png" alt="Vista visual de Ruka Costos & Recetas con sus herramientas principales"><div class="visual-copy"><span class="eyebrow">Todo en un solo lugar</span><b>Recetas, costos, pedidos y finanzas</b><p>Una mirada rápida a todo lo que Ruka puede ayudarte a organizar.</p></div></section>
      <section class="section"><div class="section-title"><div><h2>¿Qué querés hacer?</h2><p>Accesos rápidos.</p></div></div><div class="quick-grid">
        ${quick('📦','Nuevo pedido','newOrder')}${quick('🧁','Nueva receta','newRecipe')}${quick('🧮','Calcular costo','goCosts')}${quick('💸','Registrar gasto','newExpense')}
      </div></section>
      <section class="section"><div class="section-title"><div><h2>Próximas entregas</h2><p>Lo que se viene.</p></div><button class="link-btn" data-action="goOrders">Ver todos</button></div>
        <div class="card-list">${upcoming.length?upcoming.map(orderCard).join(''):`<div class="empty"><b>No hay pedidos próximos.</b>Creá un pedido cuando quieras.</div>`}</div>
      </section>
      <section class="section"><div class="section-title"><div><h2>Producción de hoy</h2><p>Tu lista de trabajo.</p></div><button class="link-btn" data-action="goProduction">Abrir producción</button></div>
        <div class="card-list">${prod.length?prod.map(productionCard).join(''):`<div class="empty"><b>No hay producción cargada hoy.</b>Podés agregar tareas desde un pedido.</div>`}</div>
      </section>`;
    bindActions(main);
  }
  function metric(label,value,sub,klass=''){ return `<div class="metric ${klass}"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div></div>`; }
  function quick(icon,label,action){ return `<button class="quick-btn" data-action="${action}"><span>${icon}</span><b>${label}</b></button>`; }

  function renderRecipes(main){
    const cats=['Todas','Favoritas',...new Set(state.recipes.map(r=>r.category).filter(Boolean))]; const list=state.recipes.filter(r=>recipeFilter==='Todas'||(recipeFilter==='Favoritas'&&r.favorite)||r.category===recipeFilter);
    main.innerHTML=`<section class="section" style="margin-top:4px"><div class="section-title"><div><h2>Mis recetas</h2><p>Tus recetas siempre a mano.</p></div><button class="primary-btn" data-action="newRecipe">＋ Nueva</button></div>
      <div class="visual-card compact"><img src="./ruka-ui-preview.png" alt="Vista de recetas y calculadora de costos de Ruka"><div class="visual-copy"><span class="eyebrow">Tu recetario digital</span><b>Guardá, calculá y actualizá</b><p>Cada receta queda conectada con sus ingredientes y costos.</p></div></div>
      <input class="search" id="recipeSearch" placeholder="🔎 Buscar receta..." aria-label="Buscar receta" />
      <div class="filter-row" style="margin-top:10px">${cats.map(c=>`<button class="filter-pill ${c===recipeFilter?'active':''}" data-recipe-filter="${esc(c)}">${esc(c)}</button>`).join('')}</div>
      <div id="recipeList" class="card-list" style="margin-top:12px">${list.length?list.map(recipeCard).join(''):`<div class="empty"><b>Aún no tenés recetas en esta categoría.</b>Creá o duplicá una receta.</div>`}</div></section>`;
    bindActions(main); $('#recipeSearch')?.addEventListener('input',e=>{ const q=e.target.value.toLowerCase(); $('#recipeList').innerHTML=state.recipes.filter(r=>(recipeFilter==='Todas'||(recipeFilter==='Favoritas'&&r.favorite)||r.category===recipeFilter)&&r.name.toLowerCase().includes(q)).map(recipeCard).join('')||'<div class="empty"><b>No encontramos recetas.</b>Probá con otro nombre.</div>'; bindActions($('#recipeList')); });
    $$('[data-recipe-filter]',main).forEach(b=>b.addEventListener('click',()=>{recipeFilter=b.dataset.recipeFilter;render('recipes')}));
  }
  function recipeCard(r){ const c=calcRecipe(r); return `<article class="card"><div class="card-head"><div><h3>${esc(r.name)} ${r.favorite?'♡':''}</h3><p>${esc(r.category||'Sin categoría')} · Rinde ${num(r.yieldQty)} ${esc(r.yieldUnit||'unidades')}</p></div><span class="tag pink">${currency(c.unitCost)}/u</span></div><div class="kpi-strip"><div class="kpi-chip"><span>Costo receta</span><b>${currency(c.total)}</b></div><div class="kpi-chip"><span>Precio sugerido</span><b>${currency(c.sellUnit)}</b></div><div class="kpi-chip"><span>Tiempo</span><b>${num(r.prepTime)+num(r.cookTime)} min</b></div></div><div class="card-actions"><button class="mini-btn" data-action="viewRecipe" data-id="${r.id}">Ver receta</button><button class="mini-btn" data-action="editRecipe" data-id="${r.id}">Editar</button><button class="mini-btn" data-action="duplicateRecipe" data-id="${r.id}">Duplicar</button></div></article>`; }

  function renderCosts(main){
    const rid=state.recipes[0]?.id||''; main.innerHTML=`<section class="section" style="margin-top:4px"><div class="section-title"><div><h2>Calculadora de costos</h2><p>Elegí una receta y mirá su costo real.</p></div></div><div class="mini-illustration"><img src="./icon-512.png" alt="Recetario y calculadora de Ruka"><div><b>De la receta al precio de venta</b><p>Ruka reúne ingredientes, mano de obra, packaging y margen para mostrarte un valor claro.</p></div></div>${state.recipes.length?`<label class="form-stack"><span class="help">Receta</span><select id="costRecipeSelect">${state.recipes.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label><div id="costWorkspace" style="margin-top:12px"></div>`:`<div class="empty"><b>Primero creá una receta.</b>Necesitamos ingredientes y rendimiento para calcular costos.<br><button class="primary-btn" data-action="newRecipe" style="margin-top:12px">Crear receta</button></div>`}</section>`;
    bindActions(main); if(state.recipes.length){ const sel=$('#costRecipeSelect'); const draw=()=>renderCostWorkspace(sel.value); sel.addEventListener('change',draw); draw(); }
  }
  function renderCostWorkspace(id){ const r=state.recipes.find(x=>x.id===id); if(!r)return; const c=calcRecipe(r); const el=$('#costWorkspace'); el.innerHTML=`
    <div class="card"><div class="card-head"><div><h3>${esc(r.name)}</h3><p>${esc(r.category)} · ${num(r.yieldQty)} ${esc(r.yieldUnit||'unidades')}</p></div><button class="mini-btn" data-action="editRecipe" data-id="${r.id}">Editar receta</button></div>
      <div class="divider"></div><div class="recipe-ingredients">${(r.ingredients||[]).map(it=>{const ing=state.ingredients.find(x=>x.id===it.ingredientId);return `<div class="card" style="padding:10px"><div class="card-head"><div><b>${esc(ing?.name||'Ingrediente')}</b><p>Usás ${num(it.qty)} ${esc(it.unit)}</p></div><b>${currency(ingredientUseCost(ing,it.qty,it.unit))}</b></div></div>`}).join('')||'<p class="muted">Sin ingredientes cargados.</p>'}</div></div>
    <div class="result-panel" style="margin-top:12px"><span class="help">Costo total de la receta</span><div class="result-big">${currency(c.total)}</div><div class="result-grid"><div class="result-item"><span>Costo por unidad</span><b>${currency(c.unitCost)}</b></div><div class="result-item"><span>Precio sugerido</span><b>${currency(c.sellUnit)}</b></div><div class="result-item"><span>Ganancia por unidad</span><b>${currency(c.profitUnit)}</b></div><div class="result-item"><span>Margen</span><b>${num(r.margin??state.settings.defaultMargin)}%</b></div></div></div>
    <div class="card" style="margin-top:12px"><h3>Desglose</h3><div class="kpi-strip"><div class="kpi-chip"><span>Ingredientes</span><b>${currency(c.ingredientCost)}</b></div><div class="kpi-chip"><span>Packaging</span><b>${currency(c.packaging)}</b></div><div class="kpi-chip"><span>Mano de obra</span><b>${currency(c.labor)}</b></div><div class="kpi-chip"><span>Servicios</span><b>${currency(c.utilities)}</b></div><div class="kpi-chip"><span>Merma</span><b>${currency(c.waste)}</b></div></div></div>`; bindActions(el); }

  function renderOrders(main){
    const orders=[...state.orders].sort((a,b)=>(b.deliveryDate+b.deliveryTime).localeCompare(a.deliveryDate+a.deliveryTime)); main.innerHTML=`<section class="section" style="margin-top:4px"><div class="section-title"><div><h2>Mis pedidos</h2><p>Entregas, señas y saldos.</p></div><button class="primary-btn" data-action="newOrder">＋ Nuevo</button></div><div class="filter-row"><button class="filter-pill active" data-order-filter="ALL">Todos</button><button class="filter-pill" data-order-filter="HOY">Hoy</button><button class="filter-pill" data-order-filter="PENDIENTE">Pendientes</button><button class="filter-pill" data-order-filter="EN PREPARACIÓN">Preparación</button><button class="filter-pill" data-order-filter="TERMINADO">Terminados</button></div><div id="ordersList" class="card-list" style="margin-top:12px">${orders.length?orders.map(orderCard).join(''):`<div class="empty"><b>Aún no hay pedidos.</b>Creá el primero para empezar.</div>`}</div></section>`; bindActions(main);
    $$('[data-order-filter]',main).forEach(b=>b.addEventListener('click',()=>{ $$('[data-order-filter]',main).forEach(x=>x.classList.remove('active')); b.classList.add('active'); const f=b.dataset.orderFilter; const l=state.orders.filter(o=>f==='ALL'||(f==='HOY'&&o.deliveryDate===todayISO())||o.status===f); $('#ordersList').innerHTML=l.map(orderCard).join('')||'<div class="empty"><b>No hay pedidos con este filtro.</b></div>'; bindActions($('#ordersList')); }));
  }
  function orderCard(o){ const c=state.customers.find(x=>x.id===o.customerId); const t=orderTotals(o); const cls=o.status==='ENTREGADO'?'success':o.status==='EN PREPARACIÓN'?'warn':o.status==='TERMINADO'?'blue':'pink'; return `<article class="card"><div class="card-head"><div><h3>${esc(o.product)}</h3><p>${esc(c?.name||'Cliente')} · ${num(o.qty)} u · ${fmtDate(o.deliveryDate)} ${esc(o.deliveryTime||'')}</p></div><span class="tag ${cls}">${esc(o.status)}</span></div><div class="kpi-strip"><div class="kpi-chip"><span>Total</span><b>${currency(t.total)}</b></div><div class="kpi-chip"><span>Cobrado</span><b>${currency(t.paid)}</b></div><div class="kpi-chip"><span>Saldo</span><b>${currency(t.balance)}</b></div></div><div class="card-actions"><button class="mini-btn" data-action="viewOrder" data-id="${o.id}">Ver</button><button class="mini-btn" data-action="editOrder" data-id="${o.id}">Editar</button><button class="mini-btn" data-action="addProduction" data-id="${o.id}">A producción</button></div></article>`; }

  function renderProduction(main){ const list=[...state.production].sort((a,b)=>b.date.localeCompare(a.date)); main.innerHTML=`<section class="section" style="margin-top:4px"><div class="section-title"><div><h2>Producción</h2><p>Qué preparar y en qué estado está.</p></div><button class="secondary-btn" data-action="newProduction">＋ Tarea</button></div><div class="card-list">${list.length?list.map(productionCard).join(''):`<div class="empty"><b>No hay tareas de producción.</b>Podés agregarlas desde un pedido.</div>`}</div></section>`; bindActions(main); }
  function productionCard(p){ return `<article class="card"><div class="card-head"><div><h3>${esc(p.product)}</h3><p>${num(p.qty)} unidades · ${fmtDate(p.date)}</p></div><span class="tag ${p.status==='Terminado'||p.status==='Empaquetado'?'success':'warn'}">${esc(p.status)}</span></div><div class="card-actions"><select class="status-select" data-prod-status="${p.id}"><option ${p.status==='Pendiente'?'selected':''}>Pendiente</option><option ${p.status==='En proceso'?'selected':''}>En proceso</option><option ${p.status==='Terminado'?'selected':''}>Terminado</option><option ${p.status==='Empaquetado'?'selected':''}>Empaquetado</option></select><button class="mini-btn" data-action="deleteProduction" data-id="${p.id}">Eliminar</button></div></article>`; }

  function renderCustomers(main){ main.innerHTML=`<section class="section" style="margin-top:4px"><div class="section-title"><div><h2>Clientes</h2><p>Tu agenda y el historial de compras.</p></div><button class="primary-btn" data-action="newCustomer">＋ Nuevo</button></div><input id="customerSearch" class="search" placeholder="🔎 Buscar cliente..."><div id="customerList" class="card-list" style="margin-top:12px">${state.customers.length?state.customers.map(customerCard).join(''):`<div class="empty"><b>No tenés clientes cargados.</b>Agregá el primero.</div>`}</div></section>`; bindActions(main); $('#customerSearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase(); $('#customerList').innerHTML=state.customers.filter(c=>c.name.toLowerCase().includes(q)).map(customerCard).join('')||'<div class="empty"><b>No encontramos clientes.</b></div>'; bindActions($('#customerList'));}); }
  function customerCard(c){ const os=state.orders.filter(o=>o.customerId===c.id); const total=os.reduce((s,o)=>s+orderTotals(o).total,0), pending=os.reduce((s,o)=>s+orderTotals(o).balance,0); return `<article class="card"><div class="card-head"><div><h3>${esc(c.name)}</h3><p>${esc(c.phone||'Sin WhatsApp')} · ${os.length} pedidos</p></div><span class="tag pink">${currency(total)}</span></div><p>Saldo pendiente: <b>${currency(pending)}</b></p><div class="card-actions"><button class="mini-btn" data-action="viewCustomer" data-id="${c.id}">Ver cliente</button><button class="mini-btn" data-action="newOrderForCustomer" data-id="${c.id}">Nuevo pedido</button></div></article>`; }

  function renderFinances(main){ const f=financeSummary(); const movements=[...state.sales.map(x=>({...x,type:'Venta',amountSigned:num(x.amount)})),...state.expenses.map(x=>({...x,type:'Gasto',amountSigned:-num(x.amount)}))].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,12); const max=Math.max(1,f.billed,f.expenses,Math.max(0,f.profit)); main.innerHTML=`<section class="section" style="margin-top:4px"><div class="section-title"><div><h2>Mis finanzas</h2><p>Ingresos, gastos y rentabilidad.</p></div></div><div class="metric-grid">${metric('Facturación',currency(f.billed),'Mes','blue')}${metric('Cobrado',currency(f.collected),'Mes','olive')}${metric('Gastos',currency(f.expenses),'Mes','pink')}${metric('Ganancia est.',currency(f.profit),'Mes','beige')}</div>
      <div class="card" style="margin-top:12px"><h3>Ingresos vs gastos</h3><div class="bar-chart" style="margin-top:12px">${bar('Ventas',f.billed,max,'var(--blue)')}${bar('Gastos',f.expenses,max,'var(--pink)')}${bar('Ganancia',Math.max(0,f.profit),max,'var(--olive)')}</div></div>
      <div class="section-title" style="margin-top:18px"><div><h2>Movimientos</h2><p>Últimos registros.</p></div><div><button class="mini-btn" data-action="newSale">＋ Ingreso</button> <button class="mini-btn" data-action="newExpense">− Gasto</button></div></div><div class="card-list">${movements.length?movements.map(m=>`<div class="card"><div class="card-head"><div><h3>${esc(m.type)} · ${esc(m.description||m.product||'Movimiento')}</h3><p>${fmtDate(m.date)}</p></div><b class="${m.amountSigned>=0?'money-positive':'money-negative'}">${m.amountSigned>=0?'+':'−'}${currency(Math.abs(m.amountSigned))}</b></div></div>`).join(''):`<div class="empty"><b>No hay movimientos.</b></div>`}</div></section>`; bindActions(main); }
  function bar(label,val,max,color){ return `<div class="bar-row"><b>${label}</b><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,val/max*100)}%;background:${color}"></div></div><span>${currency(val)}</span></div>`; }

  function renderIngredients(main){ main.innerHTML=`<section class="section" style="margin-top:4px"><div class="section-title"><div><h2>Ingredientes</h2><p>Actualizá un precio una vez y Ruka recalcula tus recetas.</p></div><button class="primary-btn" data-action="newIngredient">＋ Nuevo</button></div><div class="card-list">${state.ingredients.length?state.ingredients.map(ingredientCard).join(''):`<div class="empty"><b>No hay ingredientes.</b>Agregá los insumos que usás.</div>`}</div></section>`; bindActions(main); }
  function ingredientCard(i){ const uses=state.recipes.filter(r=>r.ingredients?.some(x=>x.ingredientId===i.id)).length; return `<article class="card"><div class="card-head"><div><h3>${esc(i.name)}</h3><p>${num(i.purchaseQty)} ${esc(i.purchaseUnit)} · ${fmtDate(i.date)}</p></div><b>${currency(i.price)}</b></div><p>Usado en ${uses} receta${uses===1?'':'s'}.</p><div class="card-actions"><button class="mini-btn" data-action="editIngredient" data-id="${i.id}">Actualizar precio</button><button class="mini-btn" data-action="priceHistory" data-id="${i.id}">Historial</button></div></article>`; }

  function renderShopping(main){ const sums=new Map(); state.production.filter(p=>['Pendiente','En proceso'].includes(p.status)).forEach(p=>{const r=state.recipes.find(x=>x.id===p.recipeId); if(!r)return; const factor=num(p.qty)/Math.max(1,num(r.yieldQty)); (r.ingredients||[]).forEach(it=>{ const ing=state.ingredients.find(x=>x.id===it.ingredientId); if(!ing)return; const key=`${ing.id}|${it.unit}`; sums.set(key,(sums.get(key)||0)+num(it.qty)*factor); });}); const rows=[...sums.entries()].map(([key,qty])=>{const [id,unit]=key.split('|'); return {ing:state.ingredients.find(x=>x.id===id),qty,unit};}); main.innerHTML=`<section class="section" style="margin-top:4px"><div class="section-title"><div><h2>Lista de compras</h2><p>Calculada desde la producción pendiente.</p></div></div>${rows.length?`<div class="card-list">${rows.map(x=>`<div class="card"><div class="card-head"><div><h3>${esc(x.ing?.name||'Ingrediente')}</h3><p>Necesitás</p></div><b>${Math.ceil(x.qty*100)/100} ${esc(x.unit)}</b></div></div>`).join('')}</div>`:`<div class="empty"><b>No hay compras calculadas.</b>Agregá pedidos a producción para generar la lista.</div>`}</section>`; }

  function renderHistory(main){ const items=[]; state.orders.forEach(x=>items.push({date:x.createdAt,type:'Pedido',title:x.product,amount:orderTotals(x).total})); state.expenses.forEach(x=>items.push({date:x.createdAt,type:'Gasto',title:x.description,amount:-num(x.amount)})); state.sales.forEach(x=>items.push({date:x.createdAt,type:'Venta',title:x.description||x.product,amount:num(x.amount)})); state.recipes.forEach(x=>items.push({date:x.createdAt,type:'Receta',title:x.name})); state.priceHistory.forEach(x=>items.push({date:x.createdAt,type:'Precio',title:x.name,amount:x.newPrice})); items.sort((a,b)=>String(b.date).localeCompare(String(a.date))); main.innerHTML=`<section class="section" style="margin-top:4px"><div class="section-title"><div><h2>Historial</h2><p>Los últimos cambios y registros.</p></div></div><div class="card-list">${items.length?items.map(x=>`<div class="card"><div class="card-head"><div><span class="tag blue">${esc(x.type)}</span><h3 style="margin-top:7px">${esc(x.title||'Registro')}</h3><p>${fmtDateTime(x.date)}</p></div>${x.amount!=null?`<b>${x.amount<0?'−':''}${currency(Math.abs(x.amount))}</b>`:''}</div></div>`).join(''):`<div class="empty"><b>Aún no hay historial.</b></div>`}</div></section>`; }

  function renderSettings(main){ main.innerHTML=`<section class="section" style="margin-top:4px"><div class="section-title"><div><h2>Configuración</h2><p>Preferencias, copia de seguridad y datos.</p></div></div><form id="settingsForm" class="card form-stack"><label>Tu nombre<input name="name" value="${esc(state.settings.name)}" required></label><label>Emprendimiento<input name="business" value="${esc(state.settings.business)}"></label><div class="form-grid"><label>Valor de tu hora<input name="hourValue" type="number" min="0" value="${num(state.settings.hourValue)}"></label><label>Margen predeterminado %<input name="defaultMargin" type="number" min="0" max="95" value="${num(state.settings.defaultMargin)}"></label></div><label>Merma predeterminada %<input name="defaultWaste" type="number" min="0" max="100" value="${num(state.settings.defaultWaste)}"></label><button class="primary-btn">Guardar configuración</button></form>
      <div class="card" style="margin-top:12px"><h3>Copia de seguridad</h3><p>Exportá tus datos para guardarlos o llevarlos a otro dispositivo.</p><div class="card-actions"><button class="mini-btn" data-action="exportData">Exportar JSON</button><button class="mini-btn" data-action="importData">Importar JSON</button><input id="importFile" type="file" accept="application/json" class="hidden"></div></div>
      <div class="card" style="margin-top:12px"><h3>Datos de demostración</h3><p>Podés eliminarlos cuando quieras y empezar desde cero.</p><button class="secondary-btn" data-action="removeDemo">Eliminar datos de demostración</button></div>
      <div class="card" style="margin-top:12px"><h3>Zona de cuidado</h3><p>Esta acción borra todos los registros guardados en este dispositivo.</p><button class="danger-btn" data-action="resetAll">Borrar todos los datos</button></div></section>`; bindActions(main); $('#settingsForm').addEventListener('submit',e=>{e.preventDefault(); const fd=new FormData(e.currentTarget); state.settings={...state.settings,name:fd.get('name').trim(),business:fd.get('business').trim(),hourValue:num(fd.get('hourValue')),defaultMargin:clamp(num(fd.get('defaultMargin')),0,95),defaultWaste:clamp(num(fd.get('defaultWaste')),0,100)}; saveState();toast('Configuración guardada.');render('settings');}); }

  function bindActions(root=document){
    $$('[data-action]',root).forEach(b=>{ if(b.dataset.bound)return; b.dataset.bound='1'; b.addEventListener('click',()=>handleAction(b.dataset.action,b.dataset.id)); });
    $$('[data-prod-status]',root).forEach(s=>{ if(s.dataset.bound)return; s.dataset.bound='1'; s.addEventListener('change',()=>{const p=state.production.find(x=>x.id===s.dataset.prodStatus); if(p){p.status=s.value;p.updatedAt=nowISO();saveState();toast('Producción actualizada.')}}); });
  }
  function handleAction(action,id){
    const map={goOrders:()=>render('orders'),goProduction:()=>render('production'),goCosts:()=>render('costs'),newRecipe:()=>recipeForm(),viewRecipe:()=>viewRecipe(id),editRecipe:()=>recipeForm(id),duplicateRecipe:()=>duplicateRecipe(id),newIngredient:()=>ingredientForm(),editIngredient:()=>ingredientForm(id),priceHistory:()=>showPriceHistory(id),newOrder:()=>orderForm(),editOrder:()=>orderForm(id),viewOrder:()=>viewOrder(id),addProduction:()=>addOrderToProduction(id),newProduction:()=>productionForm(),deleteProduction:()=>deleteProduction(id),newCustomer:()=>customerForm(),viewCustomer:()=>viewCustomer(id),newOrderForCustomer:()=>orderForm(null,id),newExpense:()=>expenseForm(),newSale:()=>saleForm(),exportData:exportData,importData:()=>$('#importFile')?.click(),removeDemo:removeDemo,resetAll:resetAll}; map[action]?.(); }

  function ingredientOptions(selected=''){ return state.ingredients.map(i=>`<option value="${i.id}" ${i.id===selected?'selected':''}>${esc(i.name)}</option>`).join(''); }
  function recipeForm(id=null){ const r=id?state.recipes.find(x=>x.id===id):{name:'',category:'Cookies',description:'',ingredients:[],procedure:'',prepTime:0,cookTime:0,temp:170,yieldQty:12,yieldUnit:'unidades',packaging:0,laborHours:0,utilities:0,decoration:0,commission:0,other:0,wastePct:state.settings.defaultWaste,margin:state.settings.defaultMargin,pricingMode:'margin',favorite:false,notes:''};
    const rows=(r.ingredients||[]).map((it,idx)=>ingredientRowHTML(it,idx)).join('');
    openModal(id?'Editar receta':'Nueva receta',`<form id="recipeForm" class="form-stack"><label>Nombre<input name="name" required value="${esc(r.name)}" placeholder="Ej.: Cookies Triple Chocolate"></label><div class="form-grid"><label>Categoría<input name="category" value="${esc(r.category)}"></label><label>Rendimiento<input name="yieldQty" type="number" min="0.01" step="0.01" required value="${num(r.yieldQty)}"></label></div><label>Descripción<textarea name="description">${esc(r.description)}</textarea></label><div><div class="section-title"><div><h2 style="font-size:16px">Ingredientes</h2></div><button type="button" id="addIngredientRow" class="mini-btn">＋ Agregar</button></div><div id="recipeIngredientRows" class="recipe-ingredients">${rows||'<p class="help" id="noIngMsg">Agregá ingredientes de tu base.</p>'}</div></div><label>Procedimiento<textarea name="procedure">${esc(r.procedure)}</textarea></label><div class="form-grid"><label>Preparación (min)<input name="prepTime" type="number" min="0" value="${num(r.prepTime)}"></label><label>Cocción (min)<input name="cookTime" type="number" min="0" value="${num(r.cookTime)}"></label><label>Temperatura °C<input name="temp" type="number" min="0" value="${num(r.temp)}"></label><label>Unidad de rendimiento<input name="yieldUnit" value="${esc(r.yieldUnit||'unidades')}"></label></div><h3>Otros costos</h3><div class="form-grid"><label>Packaging<input name="packaging" type="number" min="0" value="${num(r.packaging)}"></label><label>Horas de trabajo<input name="laborHours" type="number" min="0" step="0.1" value="${num(r.laborHours)}"></label><label>Gas / electricidad<input name="utilities" type="number" min="0" value="${num(r.utilities)}"></label><label>Decoración<input name="decoration" type="number" min="0" value="${num(r.decoration)}"></label><label>Otros<input name="other" type="number" min="0" value="${num(r.other)}"></label><label>Merma %<input name="wastePct" type="number" min="0" max="100" value="${num(r.wastePct)}"></label><label>Margen %<input name="margin" type="number" min="0" max="95" value="${num(r.margin)}"></label><label>Modo de precio<select name="pricingMode"><option value="margin" ${r.pricingMode==='margin'?'selected':''}>Margen sobre venta</option><option value="markup" ${r.pricingMode==='markup'?'selected':''}>Recargo sobre costo</option></select></label></div><label><input type="checkbox" name="favorite" ${r.favorite?'checked':''}> Marcar como favorita</label><button class="primary-btn">Guardar receta</button>${id?`<button type="button" class="danger-btn" id="deleteRecipeBtn">Eliminar receta</button>`:''}</form>`,body=>{
      let idx=(r.ingredients||[]).length; $('#addIngredientRow',body).addEventListener('click',()=>{ if(!state.ingredients.length){toast('Primero agregá un ingrediente.');return;} $('#noIngMsg',body)?.remove(); $('#recipeIngredientRows',body).insertAdjacentHTML('beforeend',ingredientRowHTML({ingredientId:state.ingredients[0].id,qty:0,unit:'g'},idx++)); bindRecipeRowDeletes(body); }); bindRecipeRowDeletes(body);
      $('#recipeForm',body).addEventListener('submit',e=>{e.preventDefault(); const fd=new FormData(e.currentTarget); const items=$$('.ingredient-row',body).map(row=>({ingredientId:$('select[name="ingredientId"]',row).value,qty:num($('input[name="qty"]',row).value),unit:$('select[name="unit"]',row).value})).filter(x=>x.ingredientId&&x.qty>0); const data={...(id?r:{}),id:id||uid('rec'),name:fd.get('name').trim(),category:fd.get('category').trim(),description:fd.get('description').trim(),ingredients:items,procedure:fd.get('procedure').trim(),prepTime:num(fd.get('prepTime')),cookTime:num(fd.get('cookTime')),temp:num(fd.get('temp')),yieldQty:Math.max(.01,num(fd.get('yieldQty'))),yieldUnit:fd.get('yieldUnit').trim()||'unidades',packaging:num(fd.get('packaging')),laborHours:num(fd.get('laborHours')),utilities:num(fd.get('utilities')),decoration:num(fd.get('decoration')),commission:0,other:num(fd.get('other')),wastePct:clamp(num(fd.get('wastePct')),0,100),margin:clamp(num(fd.get('margin')),0,95),pricingMode:fd.get('pricingMode'),favorite:fd.get('favorite')==='on',notes:'',createdAt:id?r.createdAt:nowISO(),updatedAt:nowISO()}; if(id) state.recipes[state.recipes.findIndex(x=>x.id===id)]=data; else state.recipes.push(data); saveState();closeModal();toast('Receta guardada.');render(currentScreen==='costs'?'costs':'recipes'); });
      $('#deleteRecipeBtn',body)?.addEventListener('click',()=>{if(confirm('¿Querés eliminar esta receta?')){state.recipes=state.recipes.filter(x=>x.id!==id);saveState();closeModal();toast('Receta eliminada.');render('recipes')}});
    }); }
  function ingredientRowHTML(it,idx){ return `<div class="ingredient-row"><label>Ingrediente<select name="ingredientId" required>${ingredientOptions(it.ingredientId)}</select></label><label>Cantidad<input name="qty" type="number" min="0" step="0.01" value="${num(it.qty)}"></label><label>Unidad<select name="unit"><option ${it.unit==='g'?'selected':''}>g</option><option ${it.unit==='kg'?'selected':''}>kg</option><option ${it.unit==='ml'?'selected':''}>ml</option><option ${it.unit==='l'?'selected':''}>l</option><option ${it.unit==='unidad'?'selected':''}>unidad</option><option ${it.unit==='docena'?'selected':''}>docena</option></select></label><button type="button" class="mini-btn recipe-row-remove" aria-label="Quitar ingrediente">✕</button></div>`; }
  function bindRecipeRowDeletes(root){ $$('.recipe-row-remove',root).forEach(b=>{if(!b.dataset.bound){b.dataset.bound='1';b.addEventListener('click',()=>b.closest('.ingredient-row').remove())}}); }
  function viewRecipe(id){ const r=state.recipes.find(x=>x.id===id); if(!r)return; const c=calcRecipe(r); openModal(r.name,`<p>${esc(r.description||'')}</p><div class="result-panel"><span class="help">Costo total</span><div class="result-big">${currency(c.total)}</div><div class="result-grid"><div class="result-item"><span>Costo por unidad</span><b>${currency(c.unitCost)}</b></div><div class="result-item"><span>Precio sugerido</span><b>${currency(c.sellUnit)}</b></div></div></div><h3>Ingredientes</h3><div class="card-list">${r.ingredients.map(it=>{const i=state.ingredients.find(x=>x.id===it.ingredientId);return `<div class="card"><b>${esc(i?.name||'Ingrediente')}</b><p>${num(it.qty)} ${esc(it.unit)} · ${currency(ingredientUseCost(i,it.qty,it.unit))}</p></div>`}).join('')}</div><h3>Procedimiento</h3><p>${esc(r.procedure||'Sin procedimiento cargado.')}</p><div class="card-actions"><button class="primary-btn" data-action="editRecipe" data-id="${r.id}">Editar receta</button></div>`,body=>bindActions(body)); }
  function duplicateRecipe(id){ const r=state.recipes.find(x=>x.id===id); if(!r)return; state.recipes.push({...JSON.parse(JSON.stringify(r)),id:uid('rec'),name:`${r.name} - copia`,favorite:false,demo:false,createdAt:nowISO(),updatedAt:nowISO()});saveState();toast('Receta duplicada.');render('recipes'); }

  function ingredientForm(id=null){ const i=id?state.ingredients.find(x=>x.id===id):{name:'',category:'',brand:'',purchaseQty:1,purchaseUnit:'kg',price:0,date:todayISO(),provider:'',notes:''}; openModal(id?'Actualizar ingrediente':'Nuevo ingrediente',`<form id="ingredientForm" class="form-stack"><label>Ingrediente<input name="name" required value="${esc(i.name)}"></label><div class="form-grid"><label>Categoría<input name="category" value="${esc(i.category)}"></label><label>Marca<input name="brand" value="${esc(i.brand||'')}"></label><label>Cantidad comprada<input name="purchaseQty" type="number" min="0.01" step="0.01" required value="${num(i.purchaseQty)}"></label><label>Unidad<select name="purchaseUnit"><option ${i.purchaseUnit==='kg'?'selected':''}>kg</option><option ${i.purchaseUnit==='g'?'selected':''}>g</option><option ${i.purchaseUnit==='l'?'selected':''}>l</option><option ${i.purchaseUnit==='ml'?'selected':''}>ml</option><option ${i.purchaseUnit==='unidad'?'selected':''}>unidad</option><option ${i.purchaseUnit==='docena'?'selected':''}>docena</option></select></label><label>Precio pagado<input name="price" type="number" min="0" step="0.01" required value="${num(i.price)}"></label><label>Fecha del precio<input name="date" type="date" value="${i.date||todayISO()}"></label></div><label>Proveedor<input name="provider" value="${esc(i.provider||'')}"></label><label>Notas<textarea name="notes">${esc(i.notes||'')}</textarea></label><button class="primary-btn">Guardar ingrediente</button></form>`,body=>{$('#ingredientForm',body).addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const oldPrice=num(i.price), newPrice=num(fd.get('price')); const data={...(id?i:{}),id:id||uid('ing'),name:fd.get('name').trim(),category:fd.get('category').trim(),brand:fd.get('brand').trim(),purchaseQty:Math.max(.01,num(fd.get('purchaseQty'))),purchaseUnit:fd.get('purchaseUnit'),price:newPrice,date:fd.get('date')||todayISO(),provider:fd.get('provider').trim(),notes:fd.get('notes').trim(),createdAt:id?i.createdAt:nowISO(),updatedAt:nowISO()}; if(id) state.ingredients[state.ingredients.findIndex(x=>x.id===id)]=data; else state.ingredients.push(data); if(id&&oldPrice!==newPrice){state.priceHistory.push({id:uid('price'),ingredientId:id,name:data.name,oldPrice,newPrice,date:data.date,createdAt:nowISO()}); const affected=state.recipes.filter(r=>r.ingredients?.some(x=>x.ingredientId===id)).length; toast(`Precio actualizado. Recalculamos ${affected} receta${affected===1?'':'s'}.`);} else toast('Ingrediente guardado.'); saveState();closeModal();render('ingredients');});}); }
  function showPriceHistory(id){ const i=state.ingredients.find(x=>x.id===id); const h=state.priceHistory.filter(x=>x.ingredientId===id).sort((a,b)=>b.date.localeCompare(a.date)); openModal(`Historial · ${i?.name||''}`,h.length?h.map(x=>`<div class="card"><div class="card-head"><div><b>${fmtDate(x.date)}</b><p>${currency(x.oldPrice)} → ${currency(x.newPrice)}</p></div><span class="tag ${x.newPrice>=x.oldPrice?'pink':'success'}">${x.oldPrice?Math.round((x.newPrice-x.oldPrice)/x.oldPrice*100):0}%</span></div></div>`).join(''):'<div class="empty"><b>Aún no hay cambios de precio.</b></div>'); }

  function orderForm(id=null,presetCustomerId=''){ const o=id?state.orders.find(x=>x.id===id):{customerId:presetCustomerId,recipeId:'',product:'',qty:1,unitPrice:0,paid:0,orderDate:todayISO(),deliveryDate:todayISO(),deliveryTime:'17:00',deliveryMode:'Retiro',address:'',notes:'',status:'NUEVO'}; openModal(id?'Editar pedido':'Nuevo pedido',`<form id="orderForm" class="form-stack"><label>Cliente<select name="customerId" required><option value="">Elegí un cliente</option>${state.customers.map(c=>`<option value="${c.id}" ${c.id===o.customerId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Receta vinculada <span class="muted">(opcional)</span><select name="recipeId"><option value="">Sin receta</option>${state.recipes.map(r=>`<option value="${r.id}" ${r.id===o.recipeId?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label>Producto<input name="product" required value="${esc(o.product)}"></label><div class="form-grid"><label>Cantidad<input name="qty" type="number" min="1" step="1" value="${num(o.qty)}" required></label><label>Precio unitario<input name="unitPrice" type="number" min="0" value="${num(o.unitPrice)}" required></label><label>Seña / cobrado<input name="paid" type="number" min="0" value="${num(o.paid)}"></label><label>Fecha pedido<input name="orderDate" type="date" value="${o.orderDate||todayISO()}"></label><label>Fecha entrega<input name="deliveryDate" type="date" value="${o.deliveryDate||todayISO()}" required></label><label>Hora entrega<input name="deliveryTime" type="time" value="${o.deliveryTime||'17:00'}"></label><label>Modalidad<select name="deliveryMode"><option ${o.deliveryMode==='Retiro'?'selected':''}>Retiro</option><option ${o.deliveryMode==='Envío'?'selected':''}>Envío</option></select></label><label>Estado<select name="status">${['NUEVO','CONFIRMADO','EN PREPARACIÓN','TERMINADO','ENTREGADO','CANCELADO'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></label></div><label>Dirección<input name="address" value="${esc(o.address||'')}"></label><label>Notas<textarea name="notes">${esc(o.notes||'')}</textarea></label><button class="primary-btn">Guardar pedido</button>${id?`<button type="button" class="danger-btn" id="deleteOrderBtn">Eliminar pedido</button>`:''}</form>`,body=>{ const recipeSel=$('select[name="recipeId"]',body); recipeSel.addEventListener('change',()=>{const r=state.recipes.find(x=>x.id===recipeSel.value);if(r){$('input[name="product"]',body).value=r.name;$('input[name="unitPrice"]',body).value=Math.ceil(calcRecipe(r).sellUnit/100)*100;}}); $('#orderForm',body).addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const data={...(id?o:{}),id:id||uid('ord'),customerId:fd.get('customerId'),recipeId:fd.get('recipeId'),product:fd.get('product').trim(),qty:Math.max(1,num(fd.get('qty'))),unitPrice:num(fd.get('unitPrice')),paid:num(fd.get('paid')),orderDate:fd.get('orderDate')||todayISO(),deliveryDate:fd.get('deliveryDate'),deliveryTime:fd.get('deliveryTime'),deliveryMode:fd.get('deliveryMode'),address:fd.get('address').trim(),notes:fd.get('notes').trim(),status:fd.get('status'),createdAt:id?o.createdAt:nowISO(),updatedAt:nowISO()}; if(data.paid>data.qty*data.unitPrice){toast('La seña no puede superar el total.');return;} if(id) state.orders[state.orders.findIndex(x=>x.id===id)]=data; else state.orders.push(data); if(data.status==='ENTREGADO'&&!state.sales.some(s=>s.orderId===data.id)){state.sales.push({id:uid('sale'),orderId:data.id,date:data.deliveryDate,customerId:data.customerId,product:data.product,amount:data.qty*data.unitPrice,description:`Pedido entregado: ${data.product}`,createdAt:nowISO(),updatedAt:nowISO()}); data.paid=data.qty*data.unitPrice;} saveState();closeModal();toast('Pedido guardado.');render('orders');}); $('#deleteOrderBtn',body)?.addEventListener('click',()=>{if(confirm('¿Querés eliminar este pedido?')){state.orders=state.orders.filter(x=>x.id!==id);saveState();closeModal();render('orders');}}); }); }
  function viewOrder(id){const o=state.orders.find(x=>x.id===id),c=state.customers.find(x=>x.id===o?.customerId);if(!o)return;const t=orderTotals(o);openModal(`Pedido · ${o.product}`,`<div class="result-panel"><span class="help">Saldo pendiente</span><div class="result-big">${currency(t.balance)}</div><div class="result-grid"><div class="result-item"><span>Total</span><b>${currency(t.total)}</b></div><div class="result-item"><span>Cobrado</span><b>${currency(t.paid)}</b></div></div></div><div class="card" style="margin-top:12px"><b>${esc(c?.name||'Cliente')}</b><p>Entrega: ${fmtDate(o.deliveryDate)} ${esc(o.deliveryTime||'')} · ${esc(o.deliveryMode)}</p><p>Estado: <b>${esc(o.status)}</b></p><p>${esc(o.notes||'')}</p></div><div class="card-actions"><button class="primary-btn" data-action="editOrder" data-id="${o.id}">Editar</button><button class="secondary-btn" data-action="addProduction" data-id="${o.id}">Agregar a producción</button></div>`,body=>bindActions(body));}
  function addOrderToProduction(id){ const o=state.orders.find(x=>x.id===id); if(!o)return;if(state.production.some(p=>p.orderId===id)){toast('Este pedido ya está en producción.');return;} state.production.push({id:uid('prod'),orderId:o.id,recipeId:o.recipeId,product:o.product,qty:o.qty,date:o.deliveryDate,status:'Pendiente',notes:o.notes,createdAt:nowISO(),updatedAt:nowISO()});saveState();toast('Pedido agregado a producción.'); }

  function productionForm(){ openModal('Nueva tarea de producción',`<form id="productionForm" class="form-stack"><label>Receta<select name="recipeId"><option value="">Sin receta</option>${state.recipes.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label><label>Producto<input name="product" required></label><div class="form-grid"><label>Cantidad<input name="qty" type="number" min="1" value="1"></label><label>Fecha<input name="date" type="date" value="${todayISO()}"></label></div><label>Notas<textarea name="notes"></textarea></label><button class="primary-btn">Guardar tarea</button></form>`,body=>{const rs=$('select[name="recipeId"]',body);rs.addEventListener('change',()=>{const r=state.recipes.find(x=>x.id===rs.value);if(r)$('input[name="product"]',body).value=r.name});$('#productionForm',body).addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);state.production.push({id:uid('prod'),orderId:'',recipeId:fd.get('recipeId'),product:fd.get('product').trim(),qty:Math.max(1,num(fd.get('qty'))),date:fd.get('date')||todayISO(),status:'Pendiente',notes:fd.get('notes').trim(),createdAt:nowISO(),updatedAt:nowISO()});saveState();closeModal();toast('Producción agregada.');render('production');});}); }
  function deleteProduction(id){if(confirm('¿Querés eliminar esta tarea de producción?')){state.production=state.production.filter(x=>x.id!==id);saveState();render('production')}}

  function customerForm(){openModal('Nuevo cliente',`<form id="customerForm" class="form-stack"><label>Nombre<input name="name" required></label><label>WhatsApp<input name="phone"></label><label>Instagram<input name="instagram"></label><label>Dirección<input name="address"></label><label>Notas<textarea name="notes"></textarea></label><button class="primary-btn">Guardar cliente</button></form>`,body=>{$('#customerForm',body).addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);state.customers.push({id:uid('cus'),name:fd.get('name').trim(),phone:fd.get('phone').trim(),instagram:fd.get('instagram').trim(),address:fd.get('address').trim(),notes:fd.get('notes').trim(),createdAt:nowISO(),updatedAt:nowISO()});saveState();closeModal();toast('Cliente agregado.');render('customers');});});}
  function viewCustomer(id){const c=state.customers.find(x=>x.id===id);if(!c)return;const os=state.orders.filter(o=>o.customerId===id);openModal(c.name,`<p>📱 ${esc(c.phone||'Sin WhatsApp')}</p><p>📍 ${esc(c.address||'Sin dirección')}</p><p>${esc(c.notes||'')}</p><h3>Historial de pedidos</h3>${os.length?os.map(o=>`<div class="card"><b>${esc(o.product)}</b><p>${fmtDate(o.deliveryDate)} · ${currency(orderTotals(o).total)} · Saldo ${currency(orderTotals(o).balance)}</p></div>`).join(''):'<div class="empty"><b>Sin pedidos.</b></div>'}<div class="card-actions"><button class="primary-btn" data-action="newOrderForCustomer" data-id="${id}">Nuevo pedido</button></div>`,body=>bindActions(body));}

  function expenseForm(){openModal('Registrar gasto',`<form id="expenseForm" class="form-stack"><label>Fecha<input name="date" type="date" value="${todayISO()}"></label><label>Categoría<select name="category">${['Ingredientes','Packaging','Servicios','Transporte','Publicidad','Herramientas','Equipamiento','Otros'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Descripción<input name="description" required></label><label>Monto<input name="amount" type="number" min="0" required></label><label>Nota<textarea name="notes"></textarea></label><button class="primary-btn">Guardar gasto</button></form>`,body=>{$('#expenseForm',body).addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);state.expenses.push({id:uid('exp'),date:fd.get('date')||todayISO(),category:fd.get('category'),description:fd.get('description').trim(),amount:num(fd.get('amount')),notes:fd.get('notes').trim(),createdAt:nowISO(),updatedAt:nowISO()});saveState();closeModal();toast('Gasto registrado.');render(currentScreen==='home'?'home':'finances');});});}
  function saleForm(){openModal('Registrar ingreso',`<form id="saleForm" class="form-stack"><label>Fecha<input name="date" type="date" value="${todayISO()}"></label><label>Descripción<input name="description" required></label><label>Monto<input name="amount" type="number" min="0" required></label><label>Forma de pago<select name="payment"><option>Efectivo</option><option>Transferencia</option><option>Mercado Pago</option><option>Tarjeta</option><option>Otro</option></select></label><button class="primary-btn">Guardar ingreso</button></form>`,body=>{$('#saleForm',body).addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);state.sales.push({id:uid('sale'),date:fd.get('date')||todayISO(),description:fd.get('description').trim(),amount:num(fd.get('amount')),payment:fd.get('payment'),createdAt:nowISO(),updatedAt:nowISO()});saveState();closeModal();toast('Ingreso registrado.');render('finances');});});}

  function exportData(){ const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}); const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ruka-backup-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Copia de seguridad exportada.'); }
  function setupImport(){ document.addEventListener('change',e=>{if(e.target?.id!=='importFile'||!e.target.files?.[0])return; const reader=new FileReader(); reader.onload=()=>{try{const imported=JSON.parse(reader.result);if(!imported.settings||!Array.isArray(imported.recipes))throw new Error('Formato inválido');if(confirm('Esto reemplazará los datos actuales. ¿Continuar?')){state={...defaultState(),...imported};saveState();toast('Copia importada.');render('settings');}}catch{alert('El archivo no parece ser una copia válida de Ruka.');}};reader.readAsText(e.target.files[0]);}); }
  function removeDemo(){ if(!confirm('¿Eliminar los datos de demostración?'))return; for(const k of ['ingredients','recipes','customers','orders','production','sales','expenses','notes']) state[k]=state[k].filter(x=>!x.demo); state.demoLoaded=true;saveState();toast('Datos de demostración eliminados.');render('settings'); }
  function resetAll(){ if(!confirm('Esta acción eliminará todos los registros guardados y no podrá deshacerse.'))return; const keep={...state.settings,onboarded:true}; state=defaultState();state.settings=keep;state.demoLoaded=true;saveState();toast('Todos los registros fueron eliminados.');render('home'); }

  function init(){
    $('#modalClose').addEventListener('click',closeModal); $('#modalBackdrop').addEventListener('click',closeModal); $('#sheetBackdrop').addEventListener('click',closeMore); $('#settingsBtn').addEventListener('click',()=>render('settings'));
    $$('.nav-item').forEach(b=>b.addEventListener('click',()=>b.dataset.nav==='more'?openMore():render(b.dataset.nav)));
    $$('[data-more]').forEach(b=>b.addEventListener('click',()=>{closeMore();render(b.dataset.more)})); setupImport();
    $('#onboardingForm').addEventListener('submit',e=>{e.preventDefault();state.settings.onboarded=true;state.settings.name=$('#onboardName').value.trim();state.settings.business=$('#onboardBusiness').value.trim();state.settings.currency=$('#onboardCurrency').value;if(!state.demoLoaded)demoData();saveState();$('#onboarding').classList.add('hidden');render('home');});
    if(!state.settings.onboarded){$('#onboarding').classList.remove('hidden');} else {if(!state.demoLoaded && !state.recipes.length && !state.ingredients.length){demoData();saveState();} render('home');}
    if('serviceWorker' in navigator){ window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{})); }
  }
  init();
})();
